import copy

class Prototype(ABC):
    """Abstract prototype class"""

    @abstractmethod
    def clone(self):
        pass

class Shape(Prototype):
    def __init__(self, x, y, color):
        self.x = x
        self.y = y
        self.color = color

    def clone(self):
        return copy.deepcopy(self)

class Circle(Shape):
    def __init__(self, x, y, color, radius):
        super().__init__(x, y, color)
        self.radius = radius

    def __str__(self):
        return f"Circle at ({self.x}, {self.y}), color: {self.color}, radius: {self.radius}"

class Rectangle(Shape):
    def __init__(self, x, y, color, width, height):
        super().__init__(x, y, color)
        self.width = width
        self.height = height

    def __str__(self):
        return f"Rectangle at ({self.x}, {self.y}), color: {self.color}, size: {self.width}x{self.height}"

class ShapeRegistry:
    """Registry for managing prototypes"""

    def __init__(self):
        self._prototypes = {}

    def register(self, key, prototype):
        self._prototypes[key] = prototype

    def unregister(self, key):
        del self._prototypes[key]

    def clone(self, key):
        prototype = self._prototypes.get(key)
        if prototype:
            return prototype.clone()
        return None

