from abc import ABC, abstractmethod

# Component interface
class Component(ABC):
    @abstractmethod
    def operation(self) -> str:
        pass

# Concrete component
class ConcreteComponent(Component):
    def operation(self) -> str:
        return "ConcreteComponent"

# Base decorator
class Decorator(Component):
    def __init__(self, component: Component):
        self._component = component

    def operation(self) -> str:
        return self._component.operation()

# Concrete decorators
class LoggingDecorator(Decorator):
    def operation(self) -> str:
        result = self._component.operation()
        print(f"Logging: {result}")
        return result

class TimingDecorator(Decorator):
    def operation(self) -> str:
        import time
        start = time.time()
        result = self._component.operation()
        end = time.time()
        print(f"Execution time: {end - start:.4f}s")
        return result

class CachingDecorator(Decorator):
    def __init__(self, component: Component):
        super().__init__(component)
        self._cache = {}

    def operation(self) -> str:
        cache_key = 'operation'
        if cache_key not in self._cache:
            self._cache[cache_key] = self._component.operation()
            print("Cache miss - computing result")
        else:
            print("Cache hit - returning cached result")
        return self._cache[cache_key]

class ErrorHandlingDecorator(Decorator):
    def operation(self) -> str:
        try:
            return self._component.operation()
        except Exception as e:
            print(f"Error caught: {e}")
            return "Error occurred"

# Usage - decorators can be stacked
component = ConcreteComponent()
decorated = ErrorHandlingDecorator(
    TimingDecorator(
        LoggingDecorator(
            CachingDecorator(component)
        )
    )
)

result = decorated.operation()
print(f"Result: {result}")

public class Facade {
    // Simplified interface to complex subsystem

    // Subsystem classes
    private class CPU {
        public void freeze() {
            System.out.println("CPU: Freezing...");
        }

        public void jump(long position) {
            System.out.println("CPU: Jumping to " + position);
        }

        public void execute() {
            System.out.println("CPU: Executing...");
        }
    }

    private class Memory {
        public void load(long position, byte[] data) {
            System.out.println("Memory: Loading data at " + position);
        }
    }

    private class HardDrive {
        public byte[] read(long lba, int size) {
            System.out.println("HardDrive: Reading " + size + " bytes from " + lba);
            return new byte[size];
        }
    }

    // Facade
    public static class ComputerFacade {
        private final CPU cpu;
        private final Memory memory;
        private final HardDrive hardDrive;

        private static final long BOOT_ADDRESS = 0x00;
        private static final long BOOT_SECTOR = 0x00;
        private static final int SECTOR_SIZE = 512;

        public ComputerFacade() {
            Facade facade = new Facade();
            this.cpu = facade.new CPU();
            this.memory = facade.new Memory();
            this.hardDrive = facade.new HardDrive();
        }

        public void start() {
            System.out.println("Starting computer...");
            cpu.freeze();
            memory.load(BOOT_ADDRESS, hardDrive.read(BOOT_SECTOR, SECTOR_SIZE));
            cpu.jump(BOOT_ADDRESS);
            cpu.execute();
            System.out.println("Computer started!");
        }
    }

    public static void main(String[] args) {
        ComputerFacade computer = new ComputerFacade();
        computer.start();
    }
}

interface Subject {
  request(): void;
}

class RealSubject implements Subject {
  request(): void {
    console.log('RealSubject: Handling request');
  }
}

class Proxy implements Subject {
  private realSubject: RealSubject | null = null;

  request(): void {
    if (this.checkAccess()) {
      this.realSubject = this.realSubject || new RealSubject();
      this.realSubject.request();
      this.logAccess();
    }
  }

  private checkAccess(): boolean {
    console.log('Proxy: Checking access before forwarding request');
    return true;
  }

  private logAccess(): void {
    console.log('Proxy: Logging access time');
  }
}

// Virtual Proxy - lazy initialization
class ImageProxy {
  private realImage: RealImage | null = null;
  private filename: string;

  constructor(filename: string) {
    this.filename = filename;
  }

  display(): void {
    if (!this.realImage) {
      this.realImage = new RealImage(this.filename);
    }
    this.realImage.display();
  }
}

class RealImage {
  private filename: string;

  constructor(filename: string) {
    this.filename = filename;
    this.loadFromDisk();
  }

  private loadFromDisk(): void {
    console.log(`Loading image: ${this.filename}`);
  }

  display(): void {
    console.log(`Displaying image: ${this.filename}`);
  }
}

// Caching Proxy
class CachingProxy implements Subject {
  private realSubject: RealSubject;
  private cache: Map<string, any> = new Map();

  constructor() {
    this.realSubject = new RealSubject();
  }

  request(): void {
    const cacheKey = 'request';

    if (this.cache.has(cacheKey)) {
      console.log('CachingProxy: Returning cached result');
      return this.cache.get(cacheKey);
    }

    console.log('CachingProxy: Cache miss, forwarding to real subject');
    this.realSubject.request();
    this.cache.set(cacheKey, 'result');
  }
}

from abc import ABC, abstractmethod
from typing import List

# Observer pattern for event-driven systems

class Observer(ABC):
    @abstractmethod
    def update(self, subject) -> None:
        pass

class Subject(ABC):
    def __init__(self):
        self._observers: List[Observer] = []

    def attach(self, observer: Observer) -> None:
        if observer not in self._observers:
            self._observers.append(observer)

    def detach(self, observer: Observer) -> None:
        if observer in self._observers:
            self._observers.remove(observer)

    def notify(self) -> None:
        for observer in self._observers:
            observer.update(self)

class StockMarket(Subject):
    def __init__(self):
        super().__init__()
        self._prices = {}

    def set_price(self, symbol: str, price: float) -> None:
        old_price = self._prices.get(symbol)
        self._prices[symbol] = price

        if old_price != price:
            print(f"Price changed: {symbol} ${old_price} -> ${price}")
            self.notify()

    def get_price(self, symbol: str) -> float:
        return self._prices.get(symbol, 0.0)

    def get_all_prices(self):
        return self._prices.copy()

class Investor(Observer):
    def __init__(self, name: str):
        self.name = name
        self.portfolio = {}

    def update(self, subject: StockMarket) -> None:
        prices = subject.get_all_prices()
        print(f"{self.name} notified of price changes: {prices}")
        self.rebalance_portfolio(prices)

    def rebalance_portfolio(self, prices: dict) -> None:
        # Simple rebalancing logic
        for symbol, price in prices.items():
            if price < 100:
                print(f"{self.name}: Buying {symbol}")
            elif price > 200:
                print(f"{self.name}: Selling {symbol}")

class TradingBot(Observer):
    def __init__(self, strategy: str):
        self.strategy = strategy

    def update(self, subject: StockMarket) -> None:
        prices = subject.get_all_prices()
        print(f"TradingBot ({self.strategy}) analyzing: {prices}")
        self.execute_strategy(prices)

    def execute_strategy(self, prices: dict) -> None:
        for symbol, price in prices.items():
            if self.strategy == 'momentum':
                print(f"TradingBot: Momentum trade on {symbol}")

# Usage
market = StockMarket()

investor1 = Investor("Alice")
investor2 = Investor("Bob")
bot = TradingBot("momentum")

market.attach(investor1)
market.attach(investor2)
market.attach(bot)

market.set_price("AAPL", 150.00)
market.set_price("GOOGL", 2800.00)

