interface PaymentStrategy {
  pay(amount: number): boolean;
}

class CreditCardPayment implements PaymentStrategy {
  private cardNumber: string;
  private cvv: string;

  constructor(cardNumber: string, cvv: string) {
    this.cardNumber = cardNumber;
    this.cvv = cvv;
  }

  pay(amount: number): boolean {
    console.log(`Paid $${amount} using Credit Card ****${this.cardNumber.slice(-4)}`);
    return true;
  }
}

class PayPalPayment implements PaymentStrategy {
  private email: string;

  constructor(email: string) {
    this.email = email;
  }

  pay(amount: number): boolean {
    console.log(`Paid $${amount} using PayPal account ${this.email}`);
    return true;
  }
}

class CryptoPayment implements PaymentStrategy {
  private walletAddress: string;
  private currency: string;

  constructor(walletAddress: string, currency: string = 'BTC') {
    this.walletAddress = walletAddress;
    this.currency = currency;
  }

  pay(amount: number): boolean {
    console.log(`Paid $${amount} using ${this.currency} to ${this.walletAddress}`);
    return true;
  }
}

class ShoppingCart {
  private items: Array<{ name: string; price: number }> = [];
  private paymentStrategy?: PaymentStrategy;

  addItem(name: string, price: number): void {
    this.items.push({ name, price });
  }

  setPaymentStrategy(strategy: PaymentStrategy): void {
    this.paymentStrategy = strategy;
  }

  checkout(): boolean {
    if (!this.paymentStrategy) {
      console.error('No payment strategy set');
      return false;
    }

    const total = this.items.reduce((sum, item) => sum + item.price, 0);
    return this.paymentStrategy.pay(total);
  }

  getTotal(): number {
    return this.items.reduce((sum, item) => sum + item.price, 0);
  }
}

