public class RemoteControl {
    private Command[] onCommands;
    private Command[] offCommands;
    private Command lastCommand;

    public RemoteControl(int slots) {
        onCommands = new Command[slots];
        offCommands = new Command[slots];

        Command noCommand = new NoCommand();
        for (int i = 0; i < slots; i++) {
            onCommands[i] = noCommand;
            offCommands[i] = noCommand;
        }
        lastCommand = noCommand;
    }

    public void setCommand(int slot, Command onCommand, Command offCommand) {
        onCommands[slot] = onCommand;
        offCommands[slot] = offCommand;
    }

    public void onButtonPressed(int slot) {
        onCommands[slot].execute();
        lastCommand = onCommands[slot];
    }

    public void offButtonPressed(int slot) {
        offCommands[slot].execute();
        lastCommand = offCommands[slot];
    }

    public void undoButtonPressed() {
        lastCommand.undo();
    }
}

public class NoCommand implements Command {
    @Override
    public void execute() {}

    @Override
    public void undo() {}
}

// Macro command for multiple commands
public class MacroCommand implements Command {
    private Command[] commands;

    public MacroCommand(Command[] commands) {
        this.commands = commands;
    }

    @Override
    public void execute() {
        for (Command command : commands) {
            command.execute();
        }
    }

    @Override
    public void undo() {
        for (int i = commands.length - 1; i >= 0; i--) {
            commands[i].undo();
        }
    }
}

from abc import ABC, abstractmethod
from enum import Enum

class State(ABC):
    @abstractmethod
    def insert_coin(self, machine):
        pass

    @abstractmethod
    def eject_coin(self, machine):
        pass

    @abstractmethod
    def dispense(self, machine):
        pass

class NoCoinState(State):
    def insert_coin(self, machine):
        print("Coin inserted")
        machine.set_state(machine.has_coin_state)

    def eject_coin(self, machine):
        print("No coin to eject")

    def dispense(self, machine):
        print("Insert coin first")

class HasCoinState(State):
    def insert_coin(self, machine):
        print("Coin already inserted")

    def eject_coin(self, machine):
        print("Coin ejected")
        machine.set_state(machine.no_coin_state)

    def dispense(self, machine):
        print("Dispensing product...")
        machine.set_state(machine.dispensing_state)
        machine.dispense()

class DispensingState(State):
    def insert_coin(self, machine):
        print("Please wait, dispensing...")

    def eject_coin(self, machine):
        print("Cannot eject, dispensing...")

    def dispense(self, machine):
        if machine.count > 0:
            machine.count -= 1
            print(f"Product dispensed. Remaining: {machine.count}")
            if machine.count > 0:
                machine.set_state(machine.no_coin_state)
            else:
                print("Machine is out of stock")
                machine.set_state(machine.out_of_stock_state)
        else:
            machine.set_state(machine.out_of_stock_state)

class OutOfStockState(State):
    def insert_coin(self, machine):
        print("Out of stock, coin returned")

    def eject_coin(self, machine):
        print("No coin inserted")

    def dispense(self, machine):
        print("Out of stock")

class VendingMachine:
    def __init__(self, count):
        self.count = count

        # Initialize states
        self.no_coin_state = NoCoinState()
        self.has_coin_state = HasCoinState()
        self.dispensing_state = DispensingState()
        self.out_of_stock_state = OutOfStockState()

        # Set initial state
        if count > 0:
            self.state = self.no_coin_state
        else:
            self.state = self.out_of_stock_state

    def set_state(self, state):
        self.state = state

    def insert_coin(self):
        self.state.insert_coin(self)

    def eject_coin(self):
        self.state.eject_coin(self)

    def dispense(self):
        self.state.dispense(self)

    def refill(self, count):
        self.count += count
        print(f"Refilled. Total count: {self.count}")
        if self.count > 0:
            self.state = self.no_coin_state

# Usage
machine = VendingMachine(2)
machine.insert_coin()
machine.dispense()
machine.insert_coin()
machine.dispense()
machine.insert_coin()  # Out of stock

