from typing import Iterator, List
from abc import ABC, abstractmethod

# Iterator pattern for traversing collections

class Iterator(ABC):
    @abstractmethod
    def has_next(self) -> bool:
        pass

    @abstractmethod
    def next(self):
        pass

class ConcreteIterator(Iterator):
    def __init__(self, collection: List):
        self._collection = collection
        self._position = 0

    def has_next(self) -> bool:
        return self._position < len(self._collection)

    def next(self):
        if not self.has_next():
            raise StopIteration

        item = self._collection[self._position]
        self._position += 1
        return item

class ReverseIterator(Iterator):
    def __init__(self, collection: List):
        self._collection = collection
        self._position = len(collection) - 1

    def has_next(self) -> bool:
        return self._position >= 0

    def next(self):
        if not self.has_next():
            raise StopIteration

        item = self._collection[self._position]
        self._position -= 1
        return item

class Aggregate(ABC):
    @abstractmethod
    def create_iterator(self) -> Iterator:
        pass

class BookCollection(Aggregate):
    def __init__(self):
        self._books = []

    def add_book(self, book: str):
        self._books.append(book)

    def create_iterator(self) -> Iterator:
        return ConcreteIterator(self._books)

    def create_reverse_iterator(self) -> Iterator:
        return ReverseIterator(self._books)

    def __iter__(self):
        """Python's built-in iterator protocol"""
        return iter(self._books)

class FilterIterator(Iterator):
    """Iterator with filtering capability"""

    def __init__(self, collection: List, predicate):
        self._collection = collection
        self._predicate = predicate
        self._position = 0
        self._advance_to_next_valid()

    def _advance_to_next_valid(self):
        while (self._position < len(self._collection) and 
               not self._predicate(self._collection[self._position])):
            self._position += 1

    def has_next(self) -> bool:
        return self._position < len(self._collection)

    def next(self):
        if not self.has_next():
            raise StopIteration

        item = self._collection[self._position]
        self._position += 1
        self._advance_to_next_valid()
        return item

# Usage
collection = BookCollection()
collection.add_book("Design Patterns")
collection.add_book("Clean Code")
collection.add_book("Refactoring")
