import java.util.concurrent.*;
import java.util.LinkedList;
import java.util.Queue;

public class ProducerConsumer {

    static class BoundedBuffer<T> {
        private final Queue<T> queue;
        private final int capacity;
        private final Object lock = new Object();

        public BoundedBuffer(int capacity) {
            this.capacity = capacity;
            this.queue = new LinkedList<>();
        }

        public void produce(T item) throws InterruptedException {
            synchronized (lock) {
                while (queue.size() == capacity) {
                    System.out.println("Buffer full, producer waiting...");
                    lock.wait();
                }

                queue.offer(item);
                System.out.println("Produced: " + item + " (size: " + queue.size() + ")");
                lock.notifyAll();
            }
        }

        public T consume() throws InterruptedException {
            synchronized (lock) {
                while (queue.isEmpty()) {
                    System.out.println("Buffer empty, consumer waiting...");
                    lock.wait();
                }

                T item = queue.poll();
                System.out.println("Consumed: " + item + " (size: " + queue.size() + ")");
                lock.notifyAll();
                return item;
            }
        }

        public int size() {
            synchronized (lock) {
                return queue.size();
            }
        }
    }

    static class Producer implements Runnable {
        private final BoundedBuffer<Integer> buffer;
        private final int id;

        public Producer(BoundedBuffer<Integer> buffer, int id) {
            this.buffer = buffer;
            this.id = id;
        }

        @Override
        public void run() {
            try {
                for (int i = 0; i < 5; i++) {
                    int item = id * 100 + i;
                    buffer.produce(item);
                    Thread.sleep(100);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    static class Consumer implements Runnable {
        private final BoundedBuffer<Integer> buffer;
        private final int id;

        public Consumer(BoundedBuffer<Integer> buffer, int id) {
            this.buffer = buffer;
            this.id = id;
        }

        @Override
        public void run() {
            try {
                for (int i = 0; i < 5; i++) {
                    Integer item = buffer.consume();
                    Thread.sleep(150);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        BoundedBuffer<Integer> buffer = new BoundedBuffer<>(5);

        Thread producer1 = new Thread(new Producer(buffer, 1));
        Thread producer2 = new Thread(new Producer(buffer, 2));
        Thread consumer1 = new Thread(new Consumer(buffer, 1));
        Thread consumer2 = new Thread(new Consumer(buffer, 2));

        producer1.start();
        producer2.start();
        consumer1.start();
        consumer2.start();

        producer1.join();
        producer2.join();
        consumer1.join();
        consumer2.join();

        System.out.println("All done!");
    }
}

import threading
import time

class ReadWriteLock:
    """Read-Write lock allowing multiple readers or single writer"""

    def __init__(self):
        self._readers = 0
        self._writers = 0
        self._read_ready = threading.Condition(threading.Lock())
        self._write_ready = threading.Condition(threading.Lock())

    def acquire_read(self):
        """Acquire read lock"""
        self._read_ready.acquire()
        try:
            while self._writers > 0:
                self._read_ready.wait()
            self._readers += 1
        finally:
            self._read_ready.release()

    def release_read(self):
        """Release read lock"""
        self._read_ready.acquire()
        try:
            self._readers -= 1
            if self._readers == 0:
                self._read_ready.notifyAll()
        finally:
            self._read_ready.release()

    def acquire_write(self):
        """Acquire write lock"""
        self._write_ready.acquire()
        self._writers += 1
        self._write_ready.release()

        self._read_ready.acquire()
        while self._readers > 0:
            self._read_ready.wait()
        self._read_ready.release()

    def release_write(self):
        """Release write lock"""
        self._write_ready.acquire()
        self._writers -= 1
        self._write_ready.release()

        self._read_ready.acquire()
        self._read_ready.notifyAll()
        self._read_ready.release()

class SharedResource:
    """Shared resource protected by read-write lock"""

    def __init__(self):
        self.lock = ReadWriteLock()
        self.data = {}

    def read(self, key):
        self.lock.acquire_read()
        try:
            print(f"Reading {key}: {self.data.get(key)}")
            time.sleep(0.1)  # Simulate read operation
            return self.data.get(key)
        finally:
            self.lock.release_read()

    def write(self, key, value):
        self.lock.acquire_write()
        try:
            print(f"Writing {key}: {value}")
            time.sleep(0.2)  # Simulate write operation
            self.data[key] = value
        finally:
            self.lock.release_write()

