# Repository Pattern - abstraction layer for data access

class Entity:
    def __init__(self, id: Optional[int] = None):
        self.id = id

class User(Entity):
    def __init__(self, id: Optional[int], username: str, email: str):
        super().__init__(id)
        self.username = username
        self.email = email

    def __repr__(self):
        return f"User(id={self.id}, username='{self.username}', email='{self.email}')"

class Repository(ABC):
    @abstractmethod
    def add(self, entity: Entity) -> Entity:
        pass

    @abstractmethod
    def get(self, id: int) -> Optional[Entity]:
        pass

    @abstractmethod
    def get_all(self) -> List[Entity]:
        pass

    @abstractmethod
    def update(self, entity: Entity) -> bool:
        pass

    @abstractmethod
    def delete(self, id: int) -> bool:
        pass

class InMemoryUserRepository(Repository):
    def __init__(self):
        self._storage = {}
        self._next_id = 1

    def add(self, user: User) -> User:
        if user.id is None:
            user.id = self._next_id
            self._next_id += 1
        self._storage[user.id] = user
        return user

    def get(self, id: int) -> Optional[User]:
        return self._storage.get(id)

    def get_all(self) -> List[User]:
        return list(self._storage.values())

    def update(self, user: User) -> bool:
        if user.id and user.id in self._storage:
            self._storage[user.id] = user
            return True
        return False

    def delete(self, id: int) -> bool:
        if id in self._storage:
            del self._storage[id]
            return True
        return False

    def find_by_username(self, username: str) -> Optional[User]:
        for user in self._storage.values():
            if user.username == username:
                return user
        return None

